-- Carga los 144 avisos ya registrados en la planilla.
--
-- IMPORTANTE: ejecutar UNA SOLA VEZ, después de haber corrido
-- agregar-avisos-otras-fuerzas.sql. El nombre de quien recibió cada llamado
-- se guarda tal cual estaba en la planilla (texto libre); no queda vinculado
-- a ningún usuario del sistema porque no se puede saber con certeza a qué
-- perfil corresponde cada nombre histórico.
-- ============================================================

do $$
begin
  if exists (select 1 from public.other_force_notices where notes like '%[IMP-AVISOS]%') then
    raise exception 'Ya se importaron los avisos históricos. Si querés reimportar, borralos primero.';
  end if;
end $$;

